import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Import and export design packages","description":"","frontmatter":{},"headers":[],"relativePath":"websites/portable-packages.md","filePath":"websites/portable-packages.md"}'),i={name:"websites/portable-packages.md"};function s(n,e,l,p,c,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="import-and-export-design-packages" tabindex="-1">Import and export design packages <a class="header-anchor" href="#import-and-export-design-packages" aria-label="Permalink to &quot;Import and export design packages&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release — source-reviewed draft</p><p>TransferBook+ v0.7.9 source baseline. Availability depends on installed release, permissions and configuration. Live publication is not established by this guide.</p></div><h2 id="choose-the-right-package" tabindex="-1">Choose the right package <a class="header-anchor" href="#choose-the-right-package" aria-label="Permalink to &quot;Choose the right package&quot;">​</a></h2><ul><li><code>.tbsite.json</code>: multi-page website blueprint, including its page structure and design system.</li><li><code>.tbtheme.json</code>: portable visual theme; the reference theme contract is v2.</li></ul><h2 id="safe-transfer-workflow" tabindex="-1">Safe transfer workflow <a class="header-anchor" href="#safe-transfer-workflow" aria-label="Permalink to &quot;Safe transfer workflow&quot;">​</a></h2><ol><li>Export from the relevant studio. Keep the original exported file unchanged as a recovery copy.</li><li>Transfer the file to the authorized destination by an approved local method.</li><li>Import into Website Studio for a website draft or use Template Manager for a theme package. Website Studio can also upgrade a compatible theme into a multi-page draft.</li><li>Inspect validation results, preview pages and devices, then save the draft where supported.</li></ol><h2 id="expected-result" tabindex="-1">Expected result <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Expected result&quot;">​</a></h2><p>Imports are treated as drafts. Checksums detect accidental corruption, not authenticity. They do not authorize publication or guarantee a trusted origin.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>Do not override integrity errors blindly. Re-export from the originating workspace and check compatibility. Website blueprints over 2 MB, unsafe routes, unapproved assets, raw scripts and incompatible schemas are rejected by the reference validator. See <a href="./publication-controls.html">publication controls</a>.</p><h2 id="import-choices-in-v0-7-10" tabindex="-1">Import choices in v0.7.10 <a class="header-anchor" href="#import-choices-in-v0-7-10" aria-label="Permalink to &quot;Import choices in v0.7.10&quot;">​</a></h2><p><strong>Status: source-reviewed staging release.</strong> Website Studio distinguishes website blueprints, theme packages and full workspace JSON backups.</p><p>When importing a theme, choose whether to apply theme tokens to the current site or import a new multi-page site. Review the target before proceeding; applying tokens changes the intended site&#39;s design, whereas a new site is a separate draft. Validate the package, inspect the result in each relevant locale and device, then save. Keep a pre-change export.</p><p>Use a full workspace backup only for the appropriate recovery workflow, not as a substitute for a portable design handoff. Company and operating-mode boundaries remain in force.</p>',14)])])}const g=a(i,[["render",s]]);export{u as __pageData,g as default};
